// 2025-1-21 
// 五网格法画彭罗斯镶嵌
// Penrose tiling pentagrid method
// 
// from:
// https://www.desmos.com/calculator/g4wcmzmn3s
//
#define TAU 6.28318531
float w[5]; vec2 N[5];

// Convert the intersection point expression symbol into one of the actual four vertices. The path can only move step-by-step along the edges of the actual rhombus and cannot pass through arbitrarily.
vec2 P(vec2 p, int h) {
        vec2 s = vec2(0);
        float c;
        for (int i = 0; i < 5; i++) {
                c = ceil(dot(N[i], p) + w[i] -.0005);// - length(N[i])*.001);// Why is the system so sensitive to errors?
                c += float(i == h);
                s += N[i] * c;
        }
        return s / 2.5;
}
void mainImage(out vec4 O, vec2 U) {
        vec2  R = iResolution.xy,
              u = 2.5 * (U + U + .1 - R) / R.y ;
        float e = 9., t,s;
        vec2  a, b, c, d, g, X;
        int   m, n, i, j;

        // w[]: is the offset for each group of parallel lines.
        // Given the values (.123, .234, .345, .456, .567), the offset should be such that each intersection point in the grid has exactly 2 lines. The 5 numbers should be less than ±1 and ideally not be multiples of each other.
        w = float[](.331, .271, .137, .171, .157);
        w[3] = .5+.4*cos(iTime);

        // Five real unit vectors determine the directions of five sets of parallel lines. When distributed evenly, the grid formed is a five-grid, which can be used to create a Penrose tiling.
        for (/*int i = 0*/; i < 5; i++) 
                N[i] = vec2(cos(TAU * float(i) / 5.), sin(TAU * float(i) / 5.));

        // This is a 3x3 grid (the center and its 8 neighbors), which is equivalent to two nested loops: for(int j = -1; j <= 1; j++) for(int i = -1; i <= 1; i++)
        for (/*int j = 0*/; j < 9; j++) {

                // For five directions of lines, when combining them pairwise, there are a total of (5*4/2=10) possible combinations.
                for (/*int */i = 0; i < 10; i++) {

                        // Two Direction IDs m and n
                        m = i*3%5;
                        n = (i * 3 + 1 + (i / 5) * 2)%5;

                        // Given the input coordinates, determine the g.x-th line in the m direction and the g.y-th line in the n direction.
                        g.x = dot(u, N[m]) + w[m];
                        g.y = dot(u, N[n]) + w[n];
                        g = round(g) + vec2(ivec2(j % 3, j / 3) - 1);

                        // Given two lines with directions m and n, and distances from the "origin" as g.x and g.y, find the intersection point X.  
                        // There may be a simpler method.
                        // The intersection point of every two lines determines a diamond (the intersection point is neither a vertex nor the center of the diamond, it simply represents a specific diamond).
                        X = (N[m] * (g.y - w[n]) - N[n] * (g.x - w[m])).yx * vec2(1, -1) / sin(float(m - n) / 5. * TAU);

                        // The four vertices of the rhombus (a, b, c, d) are obtained by summing the nearest edges (vectors) of the Penrose tiling.
                        a = P(X, m),
                        b = P(X, 6),
                        c = P(X, n),
                        d = a + c - b;

                        t = e;
                        // Draw four lines.
                        #define D(a, b) e = min(e, length(u - a - (b - a) * clamp(dot(u - a, b - a) * 6.25, 0., 1.)));
                        D(a, b)
                        D(b, c)
                        D(c, d)
                        D(d, a)
                        if(t != e)s=float(i);
                }
        }
        O = .7 - vec4(smoothstep(.03, 0., e))+s*.03+.1;
}









